// |     PDX|2021-04-03|     64|     45|
// |     PDX|2021-04-02|     61|     41|
// |     SEA|2021-04-03|     57|     43|
// |     SEA|2021-04-02|     54|     39|
// +-----------+----------+---------+--------+
// Clean up by deleting the table from the Databricks cluster.
spark.sql("DROP TABLE zzz_demo_temps_table")
}
}
